// Calculate next Monday's date (start of week)
const today = new Date();
const dayOfWeek = today.getDay();
const daysUntilMonday = dayOfWeek === 0 ? 1 : (8 - dayOfWeek);
const nextMonday = new Date(today);
nextMonday.setDate(today.getDate() + daysUntilMonday);
nextMonday.setHours(0, 0, 0, 0);

// Format as YYYY-MM-DD
const weekStartDate = nextMonday.toISOString().split('T')[0];

return {
  json: {
    weekStartDate: weekStartDate,
    timestamp: nextMonday.toISOString()
  }
};

// Prepare data for OpenAI
const pantryItems = $('Fetch Pantry Items').all().map(item => item.json);
const recipes = $('Fetch Recipes').all().map(item => item.json);
const weekStartDate = $('Calculate Week Start').first().json.weekStartDate;

// Format pantry items
const pantryList = pantryItems.map(item => {
  const ingredient = typeof item.ingredient === 'object' ? item.ingredient.name : item.ingredient;
  const unit = typeof item.unit === 'object' ? (item.unit.abbreviation || item.unit.name) : item.unit;
  return `${ingredient}: ${item.quantity} ${unit}`;
}).join(', ');

// Format available recipes
const recipeList = recipes.map(recipe => {
  const name = typeof recipe === 'object' && recipe.name ? recipe.name : 'Unknown';
  return name;
}).join(', ');

// Build prompt for OpenAI
const prompt = `You are a meal planning assistant. Based on the following pantry items and available recipes, suggest a weekly meal plan for the week starting ${weekStartDate}.

Available Pantry Items:
${pantryList}

Available Recipes:
${recipeList}

Please suggest 7 days of meals (breakfast, lunch, dinner) using the available ingredients and recipes. Format your response as a JSON array with this structure:
[
  {
    "day": "monday",
    "breakfast": "Recipe Name",
    "lunch": "Recipe Name",
    "dinner": "Recipe Name"
  },
  ...
]

Days should be: monday, tuesday, wednesday, thursday, friday, saturday, sunday
Meal types should be: breakfast, lunch, dinner

Only suggest meals that can be made with available ingredients. If ingredients are missing, suggest simple alternatives or note what needs to be purchased.`;

return {
  json: {
    prompt: prompt,
    pantryItems: pantryItems,
    recipes: recipes,
    weekStartDate: weekStartDate
  }
};

// Parse OpenAI response and format for API
const openaiResponse = $json;
const weekStartDate = $('Prepare OpenAI Prompt').first().json.weekStartDate;

// Extract content from OpenAI response
let content = '';
if (openaiResponse.choices && openaiResponse.choices[0]) {
  content = openaiResponse.choices[0].message.content;
} else if (openaiResponse.message) {
  content = openaiResponse.message.content;
} else if (typeof openaiResponse === 'string') {
  content = openaiResponse;
}

// Try to extract JSON from response (handle markdown code blocks)
let mealPlanData;
try {
  // Remove markdown code blocks if present
  const jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)\s*```/) || content.match(/\[\s*\{[\s\S]*\}\s*\]/);
  const jsonString = jsonMatch ? jsonMatch[1] : content;
  mealPlanData = JSON.parse(jsonString);
} catch (error) {
  throw new Error(`Failed to parse OpenAI response: ${error.message}. Content: ${content.substring(0, 200)}`);
}

// Fetch recipes to get IDs
const recipes = $('Fetch Recipes').all().map(item => item.json);
const recipeMap = {};
recipes.forEach(recipe => {
  const name = typeof recipe === 'object' && recipe.name ? recipe.name : 'Unknown';
  const id = typeof recipe === 'object' && recipe.id ? recipe.id : null;
  if (id) recipeMap[name.toLowerCase()] = id;
});

// Map days to numbers (0 = Sunday, 1 = Monday, etc.)
const dayMap = {
  'sunday': 0,
  'monday': 1,
  'tuesday': 2,
  'wednesday': 3,
  'thursday': 4,
  'friday': 5,
  'saturday': 6
};

// Build meals array for API
const meals = [];
if (Array.isArray(mealPlanData)) {
  mealPlanData.forEach(dayPlan => {
    const day = dayPlan.day ? dayMap[dayPlan.day.toLowerCase()] : null;
    if (day === null || day === undefined) return;

    // Add breakfast
    if (dayPlan.breakfast) {
      const recipeId = recipeMap[dayPlan.breakfast.toLowerCase()] || null;
      if (recipeId) {
        meals.push({
          recipe_id: recipeId,
          day: day,
          slot: 'breakfast'
        });
      }
    }

    // Add lunch
    if (dayPlan.lunch) {
      const recipeId = recipeMap[dayPlan.lunch.toLowerCase()] || null;
      if (recipeId) {
        meals.push({
          recipe_id: recipeId,
          day: day,
          slot: 'lunch'
        });
      }
    }

    // Add dinner
    if (dayPlan.dinner) {
      const recipeId = recipeMap[dayPlan.dinner.toLowerCase()] || null;
      if (recipeId) {
        meals.push({
          recipe_id: recipeId,
          day: day,
          slot: 'dinner'
        });
      }
    }
  });
}

return {
  json: {
    weekStartDate: weekStartDate,
    meals: meals,
    rawResponse: content
  }
};

// Extract plan ID and prepare meals array for splitting
const planResponse = $json;
const planId = planResponse.id || planResponse.payload?.id;
const meals = $('Parse Meal Plan').first().json.meals;

if (!planId) {
  throw new Error('Failed to create meal plan: No plan ID returned');
}

// Split meals array into individual items
const mealItems = meals.map(meal => ({
  planId: planId,
  recipe_id: meal.recipe_id,
  day: meal.day,
  slot: meal.slot
}));

return mealItems;
